SELECT ord.id, SUM( task.task_quantity * enc.length ) taskLength, SUM( task.complete_quantity * enc.length ) competeLength FROM mes_enclosure_task_order ord LEFT JOIN mes_enclosure_task task ON ord.id = task.task_order_id AND task.bool_delete_enum = 0 LEFT JOIN tech_enclosure enc ON task.product_id = enc.id AND enc.bool_delete_enum = 0 WHERE ord.id IN
#{orderId}
GROUP BY ord.id
